import {Modelo, grilla} from 'file:///C:/Users/User/Documents/github/lego-lab/taller/src/dsl.ts';

// Acacia paraguas (Vachellia tortilis): tronco corto que se abre en horqueta y copa plana y extendida.
const m = new Modelo('acacia');
const B = 'Dark_Brown';

// Encastre entre sub-armados: se calcula la posición en un borrador y se coloca con `en`.
const borrador = new Modelo('borrador').sub('b');
function afuera(sub, id, color, base, stud, op = {}) {
	const copia = borrador.poner(base.archivo.replace(/\.dat$/, ''), base.color.codigo, {en: base.tr.t});
	const p = borrador.poner(id, color, {sobre: copia, stud, ...op});
	return sub.poner(id, color, {en: p.tr.t, rot: op.giro ? `Y${op.giro}` : ''});
}

// --- 1. Suelo de sabana con el ensanche del tronco
const suelo = m.sub('suelo');
const placa = suelo.poner('41539', 'Tan');
suelo.paso();
for (const [i, j, c] of [[0, 0, 'Dark_Tan'], [6, 5, 'Dark_Tan'], [1, 6, 'Dark_Tan']]) {
	suelo.poner('3022', c, {sobre: placa, stud: [i, j]});
}
suelo.poner('32607', 'Bright_Light_Yellow', {sobre: placa, stud: [7, 0]});
suelo.poner('32607', 'Yellow', {sobre: placa, stud: [0, 3]});
suelo.poner('32607', 'Bright_Light_Yellow', {sobre: placa, stud: [5, 7]});
suelo.paso();
const pie = suelo.poner('3003', B, {sobre: placa, stud: [3, 3]});
// raíces: pendientes que abren la base hacia los cuatro lados
suelo.poner('3040b', B, {sobre: placa, stud: [3, 1], giro: 0});
suelo.poner('3040b', B, {sobre: placa, stud: [3, 5], giro: 180});
suelo.poner('3040b', B, {sobre: placa, stud: [1, 3], giro: 90});
suelo.poner('3040b', B, {sobre: placa, stud: [5, 3], giro: 270});
suelo.paso();

// --- 2. Tronco y horqueta: ladrillos desplazados un stud por capa dibujan ramas en diagonal
const tronco = m.sub('tronco');
const t1 = afuera(tronco, '3003', B, pie, [0, 0]);
tronco.paso();
let der = tronco.poner('3003', B, {sobre: t1, stud: [1, 0]});
let izq = tronco.poner('3004', B, {sobre: t1, stud: [0, 0], con: [1, 0], giro: 0});
tronco.paso();
der = tronco.poner('3003', B, {sobre: der, stud: [1, 0]});
izq = tronco.poner('3004', B, {sobre: izq, stud: [0, 0], con: [1, 0]});
tronco.paso();
der = tronco.poner('3004', B, {sobre: der, stud: [1, 0]});
izq = tronco.poner('3004', B, {sobre: izq, stud: [0, 0], con: [1, 0]});
tronco.paso();

// --- 3. Copa plana
const copa = m.sub('copa');
const viga = afuera(copa, '3034', 'Dark_Green', izq, [0, 0]);
copa.paso();
m.raiz.colocar(suelo); m.raiz.paso();
m.raiz.colocar(tronco); m.raiz.paso();
m.raiz.colocar(copa); m.raiz.paso();
m.guardar();
EOF
